function assertRangesArray(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError('ranges must be an array');
  }
}

function assertRangePair(pair) {
  if (!Array.isArray(pair) || pair.length !== 2) {
    throw new TypeError('each range must be an array of two numbers');
  }
  const start = pair[0];
  const end = pair[1];
  if (typeof start !== 'number' || typeof end !== 'number') {
    throw new TypeError('range endpoints must be numbers');
  }
  if (!Number.isFinite(start) || !Number.isFinite(end)) {
    throw new TypeError('range endpoints must be finite numbers');
  }
  if (start > end) {
    throw new RangeError('range start must not exceed end');
  }
}

export function normalizeRanges(ranges) {
  assertRangesArray(ranges);
  for (const pair of ranges) {
    assertRangePair(pair);
  }

  const live = ranges
    .map(([start, end]) => [start, end])
    .filter(([start, end]) => start < end)
    .sort((a, b) => (a[0] - b[0]) || (a[1] - b[1]));

  const merged = [];
  for (const [start, end] of live) {
    if (merged.length === 0) {
      merged.push([start, end]);
      continue;
    }
    const last = merged[merged.length - 1];
    if (start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  return merged.map(([start, end]) => [start, end]);
}

