import { normalizeRanges } from './normalize-ranges.mjs';

function subtractInterval(segment, cut) {
  const [ss, se] = segment;
  const [rs, re] = cut;
  if (re <= ss || rs >= se) {
    return [[ss, se]];
  }
  const out = [];
  if (ss < rs) {
    out.push([ss, rs]);
  }
  if (se > re) {
    out.push([re, se]);
  }
  return out;
}

export function subtractRanges(base, removed) {
  const baseNorm = normalizeRanges(base);
  const removedNorm = normalizeRanges(removed);

  let segments = baseNorm.map(([start, end]) => [start, end]);

  for (const cut of removedNorm) {
    const next = [];
    for (const seg of segments) {
      for (const piece of subtractInterval(seg, cut)) {
        next.push(piece);
      }
    }
    segments = next;
  }

  return normalizeRanges(segments);
}

