import test from 'node:test';
import assert from 'node:assert/strict';
import { subtractRanges } from '../src/subtract-ranges.mjs';
test('outside removals leave simple intervals',()=>assert.deepEqual(subtractRanges([[1,3]],[[5,8]]),[[1,3]]));
